sn_sec_int_integration.pre_validation_script:
(function validation(config) {
    try {
        if (gs.nil(config) || gs.nil(config.api_key) || gs.nil(config.authorization)) {
            return false;
        }

        var response = new x_ntsi_contrast_ap.ContrastUtilBase().getApplicationListForValidation(null, config);
        return response;
    } catch (error) {
        gs.error(error);
        throw error;
    }
})(config);

sn_sec_int_integration.validation_script:
(function validation(configId) {

    var valid = false;
    try {
        var response = new x_ntsi_contrast_ap.ContrastUtilBase().getApplicationListForValidation(configId, configId);
		if (response.getStatusCode() == 200) {
            valid = true;
        } else {
            gs.addErrorMessage('Contrast Application Vulnerability credential validation failed');
        }
        var impl = new GlideRecord('sn_sec_int_impl');
        if (impl.get(configId)) {
            impl.setValue('validation_status', valid ? 'valid' : 'invalid');
            impl.update();
        }
        return response;
    } catch (error) {
        gs.error(error);
        throw error;
    }
})(sn_sec_int_impl);
